<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import client from '../api/client'
const TYPES=['HTTP','API','TCP','PING','DNS','SSL','MSSQL','POSTGRESQL','MYSQL','MONGODB'], DB=new Set(['MSSQL','POSTGRESQL','MYSQL','MONGODB'])
const rows=ref<any[]>([]),monitors=ref<any[]>([]),summary=ref<any>({total:0,passed:0,failed:0,by_type:[],errors:[]}),loading=ref(false),detailVisible=ref(false),selected=ref<any>({})
const search=ref(''),monitor=ref(''),monitorType=ref(''),result=ref(''),timeRange=ref<[Date,Date]|null>(null),page=ref(1),pageSize=ref(20),total=ref(0)
const monitorMap=computed(()=>Object.fromEntries(monitors.value.map(m=>[m.id,m])))
const fmt=(v:any)=>v?new Date(v).toLocaleString():'—', num=(v:any,d=2)=>v===null||v===undefined||v===''?'—':Number(v).toFixed(d)
const val=(r:any,k:string)=>r[k]??r.metrics?.[k]??r.detail?.[k], name=(r:any)=>r.monitor_name||monitorMap.value[r.monitor]?.name||r.monitor
const target=(r:any)=>r.monitor_target||monitorMap.value[r.monitor]?.target||'—', kind=(r:any)=>r.monitor_type||monitorMap.value[r.monitor]?.monitor_type||'—'
function mainMetric(r:any){const t=kind(r);if(DB.has(t))return `查询 ${num(val(r,'query_time_ms'))} ms`;if(t==='PING')return `丢包 ${num(r.packet_loss,1)}%`;if(t==='SSL')return `${r.ssl_days_remaining??'—'} 天`;if(t==='DNS')return `TTL ${val(r,'ttl')??'—'}`;if(t==='HTTP'||t==='API')return r.status_code?`HTTP ${r.status_code}`:'无状态码';return r.latency_ms==null?'—':`${num(r.latency_ms)} ms`}
function typeMetrics(r:any){const t=kind(r),m=r.metrics||{},d=r.detail||{};if(DB.has(t))return [['数据库类型',m.database_type||t],['连接耗时',`${num(m.connection_time_ms)} ms`],['查询耗时',`${num(m.query_time_ms)} ms`],['查询结果',d.query_result??'—']];if(t==='PING')return [['平均延迟',`${num(m.average_ms)} ms`],['丢包率',`${num(r.packet_loss??m.packet_loss,1)}%`]];if(t==='DNS')return [['TTL',m.ttl??'—'],['响应码',d.rcode||'—'],['解析记录',(d.records||[]).join(', ')||'—']];if(t==='SSL')return [['剩余有效期',`${r.ssl_days_remaining??'—'} 天`],['到期时间',d.not_after?fmt(d.not_after):'—'],['告警状态',m.warning?'即将到期':'正常'],['颁发者',JSON.stringify(d.issuer||'—')]];if(t==='HTTP'||t==='API')return [['HTTP 状态码',r.status_code??'—'],['最终地址',d.final_url||'—'],['响应耗时',`${num(r.latency_ms)} ms`]];return [['连接耗时',`${num(r.latency_ms)} ms`]]}
function assertionText(a:any){return a.type==='status_code'?`状态码应为 ${(a.expected||[]).join(', ')}`:a.type==='keyword'?`响应包含 ${a.expected}`:a.type==='regex'?`正则匹配 ${a.expected}`:a.type==='jsonpath'?`JSONPath ${a.path}`:a.type==='dns_records'?'DNS 记录符合预期':a.type==='contains'?'返回内容符合预期':a.type||'响应断言'}
function params(){const p:any={ordering:'-checked_at'};if(search.value)p.search=search.value;if(monitor.value)p.monitor=monitor.value;if(monitorType.value)p.monitor_type=monitorType.value;if(result.value!=='')p.success=result.value;if(timeRange.value){p.checked_after=timeRange.value[0].toISOString();p.checked_before=timeRange.value[1].toISOString()}return p}
function reset(){search.value='';monitor.value='';monitorType.value='';result.value='';timeRange.value=null;page.value=1;load()}
function openDetail(r:any){selected.value=r;detailVisible.value=true}
async function load(){loading.value=true;try{const p=params(),[list,stats]=await Promise.all([client.get('/monitor-results/',{params:{...p,page:page.value,page_size:pageSize.value}}),client.get('/monitor-results/summary/',{params:p})]);rows.value=list.data.results||list.data;total.value=list.data.count??rows.value.length;summary.value=stats.data}catch(e:any){ElMessage.error(e.response?.data?.message||'探测结果加载失败')}finally{loading.value=false}}
async function init(){try{const{data}=await client.get('/monitors/',{params:{page_size:500}});monitors.value=data.results||data;await load()}catch{ElMessage.error('探测结果初始化失败')}}
onMounted(init)
</script>
<template>
<div class="page-heading"><div><h2>探测结果</h2><p>统一分析网络、接口、证书及数据库查询探测结果</p></div><el-button :loading="loading" @click="load">刷新数据</el-button></div>
<div class="metrics"><div class="metric"><span>筛选结果</span><strong>{{summary.total}}</strong><small>全量统计 · 当前第 {{page}} 页</small></div><div class="metric success"><span>成功率</span><strong>{{summary.success_rate==null?'—':summary.success_rate+'%'}}</strong><small>{{summary.passed}} 次成功</small></div><div class="metric danger"><span>失败</span><strong>{{summary.failed}}</strong><small>{{summary.errors?.[0]?.error_type||'暂无主要错误'}}</small></div><div class="metric"><span>平均响应</span><strong>{{num(summary.average_latency_ms,1)}}<em v-if="summary.average_latency_ms!=null"> ms</em></strong><small>当前全部筛选样本</small></div></div>
<el-card class="filter-card" shadow="never"><div class="filters"><el-input v-model="search" clearable placeholder="任务、目标、业务或错误信息" @keyup.enter="page=1;load()"/><el-select v-model="monitor" clearable filterable placeholder="全部探测任务"><el-option v-for="m in monitors" :key="m.id" :label="m.name" :value="m.id"/></el-select><el-select v-model="monitorType" clearable placeholder="全部类型"><el-option v-for="t in TYPES" :key="t" :label="t" :value="t"/></el-select><el-select v-model="result" clearable placeholder="全部结果"><el-option label="成功" value="true"/><el-option label="失败" value="false"/></el-select><el-date-picker v-model="timeRange" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/><el-button type="primary" @click="page=1;load()">查询</el-button><el-button @click="reset">重置</el-button></div><div v-if="summary.by_type?.length" class="type-summary"><span v-for="item in summary.by_type" :key="item.type"><b>{{item.type}}</b>{{item.total}} 次 <em v-if="item.failed">· {{item.failed}} 失败</em></span></div></el-card>
<el-card class="result-card" shadow="never"><el-table v-loading="loading" :data="rows" stripe empty-text="暂无探测结果" @row-dblclick="openDetail"><el-table-column label="业务 / 探测任务" min-width="210"><template #default="s"><div class="monitor-cell"><b>{{name(s.row)}}</b><span>{{s.row.business_name||'—'}}</span><small>{{target(s.row)}}</small></div></template></el-table-column><el-table-column label="类型" width="112"><template #default="s"><el-tag effect="plain">{{kind(s.row)}}</el-tag></template></el-table-column><el-table-column label="结果" width="96"><template #default="s"><span class="status" :class="s.row.success?'up':'down'"><i/>{{s.row.success?'成功':'失败'}}</span></template></el-table-column><el-table-column label="关键指标" width="145"><template #default="s"><b class="key-metric">{{mainMetric(s.row)}}</b><small class="duration">总耗时 {{num(s.row.latency_ms)}} ms</small></template></el-table-column><el-table-column label="结果说明" min-width="220" show-overflow-tooltip><template #default="s"><span :class="{'error-text':!s.row.success}">{{s.row.error_summary||s.row.error_type||(s.row.success?'所有检查项通过':'未知错误')}}</span></template></el-table-column><el-table-column label="探测时间" width="180"><template #default="s">{{fmt(s.row.checked_at)}}</template></el-table-column><el-table-column label="操作" width="88" fixed="right" align="center"><template #default="s"><el-button link type="primary" @click="openDetail(s.row)">查看详情</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" :total="total" @size-change="page=1;load()" @current-change="load"/></div></el-card>
<el-drawer v-model="detailVisible" title="探测结果详情" size="600px"><div class="detail-status" :class="selected.success?'ok':'bad'"><div><span>{{selected.success?'探测成功':'探测失败'}}</span><small>{{kind(selected)}} · {{name(selected)}}</small></div><b>{{num(selected.latency_ms)}} ms</b></div><h4>基本信息</h4><el-descriptions :column="1" border><el-descriptions-item label="业务系统">{{selected.business_name||'—'}}</el-descriptions-item><el-descriptions-item label="探测目标">{{target(selected)}}</el-descriptions-item><el-descriptions-item label="探测时间">{{fmt(selected.checked_at)}}</el-descriptions-item><el-descriptions-item label="执行区间">{{fmt(selected.started_at)}} 至 {{fmt(selected.finished_at)}}</el-descriptions-item><el-descriptions-item label="结果说明"><span :class="{'error-text':!selected.success}">{{selected.error_summary||'探测正常'}}</span></el-descriptions-item><el-descriptions-item v-if="selected.error_type" label="错误类型">{{selected.error_type}}</el-descriptions-item></el-descriptions><h4>{{kind(selected)}} 专项指标</h4><div class="metric-list"><div v-for="item in typeMetrics(selected)" :key="String(item[0])"><span>{{item[0]}}</span><b>{{item[1]}}</b></div></div><template v-if="selected.assertions?.length"><h4>响应断言</h4><div class="assertions"><div v-for="(a,i) in selected.assertions" :key="i" :class="a.success?'pass':'fail'"><i>{{a.success?'✓':'!'}}</i><span>{{assertionText(a)}}</span><b>{{a.success?'通过':'失败'}}</b></div></div></template><el-collapse class="raw"><el-collapse-item title="查看原始探测数据"><pre>{{JSON.stringify({metrics:selected.metrics,assertions:selected.assertions,detail:selected.detail},null,2)}}</pre></el-collapse-item></el-collapse></el-drawer>
</template>
<style scoped>
.page-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-heading h2{margin:0 0 5px;color:#17263b}.page-heading p{margin:0;color:#8290a3;font-size:14px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}.metric{background:#fff;border:1px solid #dde5ee;border-radius:8px;padding:17px 20px;box-shadow:0 2px 7px #22354d0a}.metric span,.metric small{display:block;color:#8290a3;font-size:13px}.metric strong{display:block;margin:8px 0 5px;color:#1d3048;font-size:27px}.metric strong em{font-size:13px;font-style:normal;font-weight:500}.metric.success{border-top:3px solid #36a66b}.metric.danger{border-top:3px solid #df5b5b}.filter-card{margin-bottom:14px}.filters{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.filters>.el-input{width:240px}.filters>.el-select{width:150px}.filters>.el-date-editor{width:340px}.type-summary{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px;padding-top:13px;border-top:1px solid #edf1f5}.type-summary span{padding:5px 9px;border-radius:5px;background:#f3f6f9;color:#69798d;font-size:12px}.type-summary b{margin-right:6px;color:#284766}.type-summary em{color:#c54b4b;font-style:normal}.result-card :deep(.el-card__body){padding-top:8px}.monitor-cell b,.monitor-cell span,.monitor-cell small,.key-metric,.duration{display:block}.monitor-cell span{color:#63768c;font-size:12px;margin-top:3px}.monitor-cell small{color:#929dab;margin-top:3px;max-width:250px;overflow:hidden;text-overflow:ellipsis}.status{display:inline-flex;align-items:center;gap:7px;font-weight:600}.status i{width:8px;height:8px;border-radius:50%}.status.up{color:#2b8a57}.status.up i{background:#36a66b;box-shadow:0 0 0 3px #def3e7}.status.down,.error-text{color:#c54b4b}.status.down i{background:#df5b5b;box-shadow:0 0 0 3px #fae2e2}.key-metric{color:#31465f}.duration{color:#929dac;font-size:11px;margin-top:4px}.pagination{display:flex;justify-content:flex-end;padding:16px 0 2px}.detail-status{display:flex;justify-content:space-between;align-items:center;border-radius:7px;padding:17px 19px;margin-bottom:18px}.detail-status.ok{background:#eef9f3;color:#24764d}.detail-status.bad{background:#fff1f1;color:#b94040}.detail-status span,.detail-status small{display:block}.detail-status small{margin-top:4px;opacity:.75}.detail-status b{font-size:22px}.el-drawer h4{margin:22px 0 10px;color:#27394f}.metric-list{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.metric-list>div{padding:12px;background:#f5f8fb;border:1px solid #e7edf3;border-radius:6px}.metric-list span,.metric-list b{display:block}.metric-list span{font-size:12px;color:#8290a3;margin-bottom:6px}.metric-list b{color:#283e58;word-break:break-all}.assertions{display:flex;flex-direction:column;gap:8px}.assertions>div{display:grid;grid-template-columns:25px 1fr auto;align-items:center;padding:10px;border-radius:6px;background:#f5f8fb}.assertions i{font-style:normal}.assertions .pass i,.assertions .pass b{color:#28865a}.assertions .fail i,.assertions .fail b{color:#c54b4b}.raw{margin-top:20px}.raw pre{margin:0;padding:14px;background:#0e1e30;color:#cfe0f3;border-radius:6px;white-space:pre-wrap;word-break:break-all;max-height:300px;overflow:auto}@media(max-width:1100px){.metrics{grid-template-columns:repeat(2,1fr)}}
</style>
